   324	              style={{ ...smallButton, background: palette.accent, border: 'none', color: '#fff' }}
   325	            >
   326	              Clear conversation
   327	            </button>
   328	          </div>
   329	        ) : (
   330	          <button
   331	            ref={clearButtonRef}
   332	            type="button"
   333	            onClick={() => setConfirmingClear(true)}
   334	            disabled={history.length === 0 || busy}
   335	            style={{
   336	              ...smallButton,
   337	              opacity: history.length === 0 || busy ? 0.5 : 1,
   338	              cursor: history.length === 0 || busy ? 'default' : 'pointer',
   339	            }}
   340	          >
   341	            Clear
   342	          </button>
   343	        )}
   344	      </div>
   345	
   346	      {clearFailed && (
   347	        <div role="alert" style={{ padding: '6px 20px', fontSize: '12px', color: palette.error }}>
   348	          Could not clear the conversation. Please try again.
   349	        </div>
   350	      )}
   351	
   352	      <div
   353	        ref={scrollRef}
   354	        style={{ flex: 1, overflowY: 'auto', overflowX: 'hidden', padding: '16px 20px' }}
   355	      >
   356	        {loadState === 'loading' && (
   357	          <div style={{ color: '#666', textAlign: 'center', paddingTop: '24px', fontSize: '13px' }}>
   358	            Loading conversation…
   359	          </div>
   360	        )}
   361	
   362	        {loadState === 'error' && (
   363	          <div role="alert" style={{ color: palette.error, textAlign: 'center', paddingTop: '24px', fontSize: '13px' }}>
   364	            Could not load the conversation history.{' '}
   365	            <button type="button" onClick={onReloadHistory} style={smallButton}>Try again</button>
   366	          </div>
   367	        )}
   368	
   369	        {showEmpty && (
   370	          <div style={{ color: '#888', textAlign: 'center', paddingTop: '32px', fontSize: '13px', lineHeight: 1.6 }}>
   371	            <div style={{ fontSize: '15px', color: palette.text, marginBottom: '6px' }}>No questions yet</div>
   372	            Ask a question below. Each answer will appear here with the sources it cites,
   373	            <br />
   374	            and the conversation is kept between sessions.
   375	            {documentCount === 0 && (
   376	              <div style={{ marginTop: '8px', color: palette.muted }}>
   377	                Tip: import and index documents first so answers can cite them.
   378	              </div>
   379	            )}
   380	          </div>
   381	        )}
   382	
   383	        <div role="log" aria-live="polite" aria-label="Conversation messages">
   384	          <ol style={{ listStyle: 'none', display: 'flex', flexDirection: 'column', gap: '20px' }}>
   385	            {history.map((item, i) => (
   386	              <li key={`${item.response.timestamp}-${i}`}>
   387	                <Exchange
   388	                  item={item}
   389	                  index={i}
   390	                  total={history.length}
   391	                  selectedDocId={selectedDocId}
   392	                  unavailable={unavailable}
   393	                  onActivate={handleActivate}
   394	                />
   395	              </li>
   396	            ))}
   397	
   398	            {pendingQuestion !== null && (
   399	              <li key="pending">
   400	                <article aria-label="Question awaiting an answer" aria-busy="true" style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
   401	                  <UserTurn question={pendingQuestion} />
   402	                  <div style={{
   403	                    padding: '12px 14px',
   404	                    background: palette.card,
   405	                    border: `1px dashed ${palette.border}`,
   406	                    borderRadius: '8px 8px 8px 2px',
   407	                  }}>
   408	                    <div style={turnLabel}>Assistant</div>
   409	                    <div style={{ ...textBlock, color: palette.muted, fontStyle: 'italic' }}>Answering…</div>
   410	                  </div>
   411	                </article>
   412	              </li>
   413	            )}
   414	
   415	            {askError !== null && (
   416	              <li key="error">
   417	                <article aria-label="Question that could not be answered" style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
   418	                  <UserTurn question={askError.question} />
   419	                  <div role="alert" style={{
   420	                    padding: '12px 14px',
   421	                    background: palette.card,
   422	                    border: `1px solid ${palette.error}`,
   423	                    borderRadius: '8px 8px 8px 2px',
   424	                  }}>
   425	                    <div style={{ ...turnLabel, color: palette.error }}>Not answered</div>
   426	                    <div style={{ fontSize: '13px', lineHeight: 1.5 }}>
   427	                      The question could not be answered.
   428	                    </div>
   429	                    <div style={{ fontSize: '12px', color: palette.muted, marginTop: '4px', overflowWrap: 'anywhere' }}>
   430	                      Details: {askError.message}
   431	                    </div>
   432	                    <div style={{ display: 'flex', gap: '8px', marginTop: '10px' }}>
   433	                      <button
   434	                        type="button"
   435	                        onClick={() => onRetry(askError.question)}
   436	                        disabled={busy}
   437	                        style={{ ...smallButton, background: palette.accent, border: 'none', color: '#fff' }}
   438	                      >
   439	                        Retry
   440	                      </button>
   441	                      <button type="button" onClick={onDismissError} style={smallButton}>
   442	                        Dismiss
   443	                      </button>
   444	                    </div>
   445	                  </div>
   446	                </article>
   447	              </li>
   448	            )}
   449	          </ol>
   450	        </div>
   451	      </div>
   452	    </section>
   453	  );
   454	}
