import { useState, useCallback, useEffect, useRef } from 'react';
import { DocumentList } from './components/DocumentList';
import { QuestionPanel } from './components/QuestionPanel';
import { DocumentDetail } from './components/DocumentDetail';
import { ConversationView, AskError, HistoryLoadState } from './components/ConversationView';
import { StatusBar } from './components/StatusBar';
import { describeAskError } from './components/conversation-format';
import { Document, AppStatus, Citation, QAHistory } from '../shared/types';

export function App() {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [selectedDoc, setSelectedDoc] = useState<Document | null>(null);
  const [appStatus, setAppStatus] = useState<AppStatus>({
    documentsLoaded: 0,
    indexStatus: 'idle',
    lastActivity: '',
  });
  const [conversationHistory, setConversationHistory] = useState<QAHistory[]>([]);
  const [historyLoadState, setHistoryLoadState] = useState<HistoryLoadState>('loading');
  const [pendingQuestion, setPendingQuestion] = useState<string | null>(null);
  const [askError, setAskError] = useState<AskError | null>(null);
  // Synchronous guard: state updates are async, so two rapid submits could both see pendingQuestion === null.
  const askInFlight = useRef(false);

  const refreshDocuments = useCallback(async () => {
    try {
      const docs = await window.knowledgeBase.documents.list();
      setDocuments(docs);
      const status = await window.knowledgeBase.indexing.status();
      setAppStatus(status);
    } catch (err) {
      console.error('Failed to refresh documents:', err);
    }
  }, []);

  /** Loads the persisted conversation. Returns null if it could not be read. */
  const loadHistory = useCallback(async (): Promise<QAHistory[] | null> => {
    try {
      const history = await window.knowledgeBase.conversation.get();
      setConversationHistory(history);
      setHistoryLoadState('loaded');
      return history;
    } catch {
      // Keep whatever is already on screen; only report an error if nothing was ever loaded.
      setHistoryLoadState(prev => (prev === 'loading' ? 'error' : prev));
      return null;
    }
  }, []);

  useEffect(() => {
    refreshDocuments();
    loadHistory();
  }, [refreshDocuments, loadHistory]);

  const handleImport = useCallback(async () => {
    console.log('Import triggered - use window.knowledgeBase.documents.import(filePath)');
  }, []);

  const handleSelectDocument = useCallback((doc: Document) => {
    setSelectedDoc(doc);
  }, []);

  const handleAskQuestion = useCallback(async (question: string) => {
    if (askInFlight.current) return;
    askInFlight.current = true;
    setAskError(null);
    setPendingQuestion(question);
    try {
      const response = await window.knowledgeBase.qa.ask(question);
      // The service persists the exchange before replying, so the reloaded history already
      // contains it. Replace the optimistic turn with the persisted one in the same synchronous
      // block so no render shows the question twice.
      let persisted: QAHistory[] | null = null;
      try {
        persisted = await window.knowledgeBase.conversation.get();
      } catch {
        persisted = null;
      }
      if (persisted) {
        setConversationHistory(persisted);
        setHistoryLoadState('loaded');
      } else {
        setConversationHistory(prev => [...prev, { question, response }]);
      }
      setPendingQuestion(null);
    } catch (err) {
      setAskError({ question, message: describeAskError(err) });
      setPendingQuestion(null);
    } finally {
      askInFlight.current = false;
    }
  }, []);

  const handleOpenCitation = useCallback(async (citation: Citation): Promise<boolean> => {
    const known = documents.find(d => d.id === citation.documentId);
    if (known) {
      setSelectedDoc(known);
      return true;
    }
    // The list may be stale (e.g. documents seeded since the last refresh); ask main directly.
    try {
      const doc = await window.knowledgeBase.documents.get(citation.documentId);
      if (!doc) return false;
      setSelectedDoc(doc);
      refreshDocuments();
      return true;
    } catch {
      return false;
    }
  }, [documents, refreshDocuments]);

  const handleClearConversation = useCallback(async (): Promise<boolean> => {
    try {
      await window.knowledgeBase.qa.clearHistory();
      setAskError(null);
      const reloaded = await loadHistory();
      if (reloaded === null) setConversationHistory([]);
      return true;
    } catch {
      return false;
    }
  }, [loadHistory]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
      <header style={{
        padding: '12px 20px',
        background: '#16213e',
        borderBottom: '1px solid #0f3460',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
      }}>
        <h1 style={{ fontSize: '18px', fontWeight: 600 }}>Knowledge Base</h1>
        <button
          onClick={refreshDocuments}
          style={{
            padding: '6px 14px',
            background: '#0f3460',
            color: '#e0e0e0',
            border: '1px solid #1a1a4e',
            borderRadius: '4px',
            cursor: 'pointer',
            fontSize: '13px',
          }}
        >
          Refresh
        </button>
      </header>

      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
        {/* Left panel: document list */}
        <div style={{
          width: '280px',
          flexShrink: 0,
          borderRight: '1px solid #0f3460',
          display: 'flex',
          flexDirection: 'column',
          background: '#16213e',
        }}>
          <div style={{
            padding: '8px 16px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            borderBottom: '1px solid #0f3460',
          }}>
            <h2 style={{ fontSize: '12px', fontWeight: 500 }}>
              Documents ({documents.length})
            </h2>
            <button
              onClick={handleImport}
              style={{
                padding: '4px 10px',
                background: '#533483',
                color: '#fff',
                border: 'none',
                borderRadius: '3px',
                cursor: 'pointer',
                fontSize: '12px',
              }}
            >
              + Import
            </button>
          </div>
          <DocumentList
            documents={documents}
            onSelect={handleSelectDocument}
            selectedId={selectedDoc?.id ?? null}
          />
        </div>

        {/* Right panel: selected document (if any) above the conversation and question input */}
        <main style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
          {selectedDoc && (
            <section
              aria-label="Selected document"
              style={{
                flexShrink: 0,
                maxHeight: '40%',
                overflow: 'auto',
                padding: '16px 20px',
                borderBottom: '1px solid #0f3460',
                position: 'relative',
              }}
            >
              <button
                type="button"
                onClick={() => setSelectedDoc(null)}
                aria-label="Close document"
                style={{
                  float: 'right',
                  padding: '4px 10px',
                  background: 'transparent',
                  color: '#8888bb',
                  border: '1px solid #0f3460',
                  borderRadius: '4px',
                  cursor: 'pointer',
                  fontSize: '12px',
                }}
              >
                Close
              </button>
              <DocumentDetail key={selectedDoc.id} document={selectedDoc} />
            </section>
          )}

          <ConversationView
            history={conversationHistory}
            loadState={historyLoadState}
            pendingQuestion={pendingQuestion}
            askError={askError}
            documentCount={documents.length}
            selectedDocId={selectedDoc?.id ?? null}
            onOpenCitation={handleOpenCitation}
            onRetry={handleAskQuestion}
            onDismissError={() => setAskError(null)}
            onReloadHistory={loadHistory}
            onClear={handleClearConversation}
          />

          <QuestionPanel onAsk={handleAskQuestion} busy={pendingQuestion !== null} />
        </main>
      </div>

      <StatusBar status={appStatus} />
    </div>
  );
}

