67	}
68	
69	function UserTurn({ question }: { question: string }) {
70	  return (
71	    <div style={{
72	      alignSelf: 'flex-end',
73	      maxWidth: '85%',
74	      minWidth: 0,
75	      padding: '10px 14px',
76	      background: palette.border,
77	      borderRadius: '8px 8px 2px 8px',
