156	function Exchange({
157	  item,
158	  index,
159	  total,
160	  selectedDocId,
161	  unavailable,
162	  onActivate,
163	}: {
164	  item: QAHistory;
165	  index: number;
166	  total: number;
167	  selectedDocId: string | null;
168	  unavailable: Set<string>;
169	  onActivate: (citation: Citation, key: string) => void;
170	}) {
171	  const { response } = item;
172	  const confidence = describeConfidence(response.confidence);
173	  return (
174	    <article
175	      aria-label={`Exchange ${index + 1} of ${total}`}
176	      style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}
177	    >
178	      <UserTurn question={item.question} />
179	      <div style={{
180	        alignSelf: 'stretch',
181	        minWidth: 0,
182	        padding: '12px 14px',
183	        background: palette.card,
184	        border: `1px solid ${palette.border}`,
185	        borderRadius: '8px 8px 8px 2px',
186	      }}>
187	        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '4px 12px', alignItems: 'baseline', ...turnLabel }}>
188	          <span>Assistant</span>
189	          <time
190	            dateTime={response.timestamp}
191	            style={{ textTransform: 'none', letterSpacing: 0, fontWeight: 400 }}
192	          >
193	            {formatTimestamp(response.timestamp)}
194	          </time>
195	          <span style={{ textTransform: 'none', letterSpacing: 0, fontWeight: 400 }}>
196	            <span
197	              aria-hidden="true"
198	              style={{
199	                display: 'inline-block',
200	                width: '40px',
201	                height: '6px',
202	                marginRight: '6px',
203	                background: palette.border,
204	                borderRadius: '3px',
205	                overflow: 'hidden',
206	                verticalAlign: 'middle',
207	              }}
