import React, { useState } from 'react';

interface Props {
  onAsk: (question: string) => void;
  /** True while an answer is pending; submissions are ignored until it settles. */
  busy: boolean;
}

export function QuestionPanel({ onAsk, busy }: Props) {
  const [question, setQuestion] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (busy || !question.trim()) return;
    onAsk(question.trim());
    setQuestion('');
  };

  return (
    <form
      onSubmit={handleSubmit}
      aria-label="Ask a question"
      style={{
        display: 'flex',
        padding: '12px 20px',
        borderTop: '1px solid #0f3460',
        background: '#16213e',
      }}
    >
      <label htmlFor="question-input" style={{
        position: 'absolute',
        width: '1px',
        height: '1px',
        overflow: 'hidden',
        clip: 'rect(0 0 0 0)',
        whiteSpace: 'nowrap',
      }}>
        Question about your documents
      </label>
      <input
        id="question-input"
        type="text"
        value={question}
        onChange={e => setQuestion(e.target.value)}
        placeholder="Ask a question about your documents..."
        autoComplete="off"
        style={{
          flex: 1,
          minWidth: 0,
          padding: '10px 14px',
          background: '#1a1a2e',
          color: '#e0e0e0',
          border: '1px solid #0f3460',
          borderRadius: '6px',
          fontSize: '14px',
        }}
      />
      {/* aria-disabled (not disabled) keeps focus on the button while an answer is pending. */}
      <button
        type="submit"
        aria-disabled={busy}
        style={{
          marginLeft: '10px',
          padding: '10px 20px',
          background: '#533483',
          color: '#fff',
          border: 'none',
          borderRadius: '6px',
          cursor: busy ? 'progress' : 'pointer',
          opacity: busy ? 0.6 : 1,
          fontSize: '14px',
          fontWeight: 500,
        }}
      >
        {busy ? 'Answering…' : 'Ask'}
      </button>
    </form>
  );
}
/**
 * Display-only formatting helpers for the conversation view.
 * Pure functions so they can be unit-tested without a DOM.
 */

/** Formats an ISO timestamp as a readable local date and time, e.g. "Nov 15, 2026, 10:42 PM". */
export function formatTimestamp(iso: string, locale?: string): string {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return 'Unknown time';
  return date.toLocaleString(locale, { dateStyle: 'medium', timeStyle: 'short' });
}

export type ConfidenceLevel = 'High' | 'Medium' | 'Low';

/** Maps a 0..1 confidence score to a percentage and a text label (never colour alone). */
export function describeConfidence(confidence: number): { percent: number; level: ConfidenceLevel } {
  const clamped = Number.isFinite(confidence) ? Math.min(1, Math.max(0, confidence)) : 0;
  const percent = Math.round(clamped * 100);
  const level: ConfidenceLevel = clamped >= 0.7 ? 'High' : clamped >= 0.4 ? 'Medium' : 'Low';
  return { percent, level };
}

/** Turns an IPC rejection into a short, user-facing message. */
export function describeAskError(err: unknown): string {
  const raw = err instanceof Error ? err.message : String(err);
  // Electron prefixes rejections with "Error invoking remote method '<channel>': ".
  const cleaned = raw.replace(/^Error invoking remote method '[^']+':\s*/, '').trim();
  return cleaned || 'Unknown error';
}
